import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.es-12sf8.js";var i=JSON.parse(`{"title":"Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"usage/benchmark.md","filePath":"en/usage/benchmark.md","lastUpdated":1786164232000}`),a={name:`usage/benchmark.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="benchmark" tabindex="-1">Benchmark <a class="header-anchor" href="#benchmark" aria-label="Permalink to “Benchmark”">​</a></h1><p>All benchmark results are recorded here, see <a href="./../deep-dive/benchmarking">deep dive: benchmarking</a> for benchmarking details. Sync Engine welcomes everyone contributing benchmarking results as long as it follows the steps specified in the spec.</p><h2 id="apparent-statistics" tabindex="-1">Apparent Statistics <a class="header-anchor" href="#apparent-statistics" aria-label="Permalink to “Apparent Statistics”">​</a></h2><p>Startup speed measures the time by which the plugin delays the cold start of Obsidian APP.</p><table tabindex="0"><thead><tr><th></th><th>Sync Engine<sup class="footnote-ref"><a href="#footnote1">[1]</a><a class="footnote-anchor" id="footnote-ref1"></a></sup></th><th>Remotely Save</th><th>Nextcloud Sync</th></tr></thead><tbody><tr><td>Version</td><td>3.0.0</td><td>0.5.25</td><td>0.7.38</td></tr><tr><td>Startup Time</td><td>25.4 ms</td><td>251 ms</td><td><strong>18.6 ms</strong></td></tr><tr><td>Plugin Size</td><td><strong>145 KB</strong></td><td>4050 KB</td><td>515 KB</td></tr></tbody></table><h2 id="webdav-performance" tabindex="-1">WebDAV Performance <a class="header-anchor" href="#webdav-performance" aria-label="Permalink to “WebDAV Performance”">​</a></h2><ul><li><strong>Obsidian version</strong>: 1.13.4</li><li><strong>Operating system</strong>: NixOS 26.11</li><li><strong>CPU single core score</strong>: around 1700</li><li><strong>Backend</strong>: Self-hosted Nextcloud WebDAV<sup class="footnote-ref"><a href="#footnote2">[2]</a><a class="footnote-anchor" id="footnote-ref2"></a></sup></li><li><strong>Average ping</strong>: 400 ms</li><li><strong>Average upload speed</strong>: 2.6 MiB/s</li><li><strong>Average download speed</strong>: 4.8 MiB/s</li></ul><table tabindex="0"><thead><tr><th>Item</th><th>Sync Engine</th><th>Remotely Save</th><th>Nextcloud Sync</th></tr></thead><tbody><tr><td>Version</td><td>3.0.0 + <code>webdav</code> module 0.1.7</td><td>0.5.25</td><td>0.7.38</td></tr><tr><td>2000 files upload</td><td><strong>9.43 min</strong></td><td>16.4 min</td><td>17.95 min</td></tr><tr><td>2000 files download</td><td>5.87 min</td><td>13.68 min</td><td><strong>5.22 min</strong></td></tr><tr><td>Daily simulation<br>(Original, 10 rounds)</td><td>Min: <strong>1.04 s</strong><br>Median: <strong>1.44 s</strong><br>Max: <strong>48.56 s</strong></td><td>Min: 99 s<br>Median: 129 s<br>Max: 326 s</td><td>Min: 1.27 s<br>Median: 2.75 s<br>Max: 60.55 s</td></tr><tr><td>Daily simulation<br>(Replica, 10 rounds)</td><td>Min: 1.06 s<br>Median: <strong>1.72 s</strong><br>Max: <strong>3.49 s</strong></td><td>Min: 111 s<br>Median: 117 s<br>Max: 204 s</td><td>Min: <strong>0.4 s</strong><br>Median: 3.94 s<br>Max: 55.33 s</td></tr><tr><td>Correctness validation</td><td>0 errors</td><td>0 errors</td><td><span style="color:var(--rose);font-weight:bold;">98 errors</span></td></tr></tbody></table><p>In terms of syncing performance, Sync Engine is visibly faster than Remotely Save in terms of full upload and download. In the more realistic daily sync test, Remotely Save fails catastrophically and Sync Engine is around <strong>100x faster</strong> than Remotely Save.</p><p>Although claimed to be optimized for Nextcloud, Nextcloud Sync still shows visible disadvantage in terms of performance compared with Sync Engine. More importantly, it <strong>fails to sync 98 original files or changes to the replica</strong>, and many errors appeared during the testing process.</p><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="footnote1" class="footnote-item"><p>The startup speed of Sync Engine is measured with a module loaded. <a href="#footnote-ref1" class="footnote-backref">↩︎</a></p></li><li id="footnote2" class="footnote-item"><p>During local testing, Nextcloud connection is delayed and bandwidth is limited to simulate middle-to-low network quality. <a href="#footnote-ref2" class="footnote-backref">↩︎</a></p></li></ol></section>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};